#include <vector>
#include <string>
using namespace std;

class Solution {
    long long comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r == 0 || r == n) return 1;
        long long res = 1;
        for (int i = 1; i <= r; ++i) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int v = destination[0], h = destination[1];
        int total = v + h;
        string res = "";
        for (int i = 0; i < total; ++i) {
            if (h > 0) {
                long long paths = comb(h - 1 + v, h - 1);
                if (k <= paths) {
                    res += 'H';
                    h--;
                } else {
                    res += 'V';
                    k -= paths;
                    v--;
                }
            } else {
                res += 'V';
                v--;
            }
        }
        return res;
    }
};

class Solution {
    private long comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r == 0 || r == n) return 1;
        long res = 1;
        for (int i = 1; i <= r; ++i) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }

    public String kthSmallestPath(int[] destination, int k) {
        int v = destination[0], h = destination[1];
        int total = v + h;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < total; ++i) {
            if (h > 0) {
                long paths = comb(h - 1 + v, h - 1);
                if (k <= paths) {
                    sb.append('H');
                    h--;
                } else {
                    sb.append('V');
                    k -= paths;
                    v--;
                }
            } else {
                sb.append('V');
                v--;
            }
        }
        return sb.toString();
    }
}

