var kthSmallestPath = function(destination, k) {
    let [v, h] = destination;
    function comb(n, r) {
        if (r < 0 || r > n) return 0;
        if (r === 0 || r === n) return 1;
        let res = 1;
        for (let i = 1; i <= r; ++i) {
            res = (res * (n - i + 1)) / i;
        }
        return res;
    }
    const total = v + h;
    const res = [];
    for (let i = 0; i < total; ++i) {
        if (h > 0) {
            const paths = comb(h - 1 + v, h - 1);
            if (k <= paths) {
                res.push('H');
                h--;
            } else {
                res.push('V');
                k -= paths;
                v--;
            }
        } else {
            res.push('V');
            v--;
        }
    }
    return res.join('');
